import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.function.Supplier;

public class DistributedCacheClient {

    private final ConcurrentHashMap<String, CacheEntry> localCache = new ConcurrentHashMap<>();
    private final CircuitBreaker circuitBreaker;
    private final ScheduledExecutorService evictionScheduler;
    private final AtomicLong sequenceCounter = new AtomicLong(0);

    public DistributedCacheClient(int failureThreshold, long resetTimeoutMs) {
        this.circuitBreaker = new CircuitBreaker(failureThreshold, resetTimeoutMs);
        this.evictionScheduler = Executors.newSingleThreadScheduledExecutor();
        this.evictionScheduler.scheduleAtFixedRate(this::evictExpired, 1, 1, TimeUnit.SECONDS);
    }

    public String get(String key, Supplier<String> remoteLoader) {
        CacheEntry entry = localCache.get(key);
        if (entry != null && !entry.isExpired()) {
            return entry.getValue();
        }

        if (circuitBreaker.getState() == CircuitState.OPEN) {
            return entry != null ? entry.getValue() : null; // stale fallback
        }

        try {
            String value = circuitBreaker.execute(() -> remoteLoader.get());
            long seq = sequenceCounter.getAndIncrement();
            CacheEntry newEntry = new CacheEntry(value, System.currentTimeMillis() + 30000, seq);
            localCache.put(key, newEntry);
            return value;
        } catch (Exception e) {
            return entry != null ? entry.getValue() : null;
        }
    }

    public void put(String key, String value) {
        if (circuitBreaker.getState() == CircuitState.OPEN) {
            throw new IllegalStateException("Circuit breaker is open");
        }

        long seq = sequenceCounter.getAndIncrement();
        CacheEntry newEntry = new CacheEntry(value, System.currentTimeMillis() + 30000, seq);
        localCache.put(key, newEntry);

        try {
            circuitBreaker.execute(() -> {
                simulateRemoteWrite(key, value);
                return null;
            });
        } catch (Exception e) {
            // Write-behind: entry stays in local cache for retry
        }
    }

    public void invalidate(String key, long remoteSequence) {
        localCache.compute(key, (k, current) -> {
            if (current == null) {
                return null;
            }
            // Only invalidate if remote sequence is newer
            if (remoteSequence > current.getSequence()) {
                return null; // remove
            }
            return current; // keep
        });
    }

    private void evictExpired() {
        long now = System.currentTimeMillis();
        localCache.entrySet().removeIf(e -> e.getValue().isExpiredAt(now));
    }

    private void simulateRemoteWrite(String key, String value) {
        // Simulates network call to distributed cache cluster
        try { Thread.sleep(10); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
    }

    // --- Inner Classes ---

    enum CircuitState { CLOSED, OPEN, HALF_OPEN }

    static class CacheEntry {
        private final String value;
        private final long expiresAt;
        private final long sequence;

        CacheEntry(String value, long expiresAt, long sequence) {
            this.value = value;
            this.expiresAt = expiresAt;
            this.sequence = sequence;
        }

        String getValue() { return value; }
        long getSequence() { return sequence; }
        boolean isExpired() { return System.currentTimeMillis() > expiresAt; }
        boolean isExpiredAt(long now) { return now > expiresAt; }
    }

    static class CircuitBreaker {
        private volatile CircuitState state = CircuitState.CLOSED;
        private final AtomicInteger failureCount = new AtomicInteger(0);
        private final int failureThreshold;
        private final long resetTimeoutMs;
        private volatile long lastFailureTime = 0;
        private final Object halfOpenLock = new Object();

        CircuitBreaker(int failureThreshold, long resetTimeoutMs) {
            this.failureThreshold = failureThreshold;
            this.resetTimeoutMs = resetTimeoutMs;
        }

        CircuitState getState() {
            if (state == CircuitState.OPEN) {
                if (System.currentTimeMillis() - lastFailureTime > resetTimeoutMs) {
                    state = CircuitState.HALF_OPEN;
                }
            }
            return state;
        }

        <T> T execute(Supplier<T> action) {
            CircuitState currentState = getState();
            if (currentState == CircuitState.OPEN) {
                throw new RuntimeException("Circuit breaker is open");
            }

            if (currentState == CircuitState.HALF_OPEN) {
                synchronized (halfOpenLock) {
                    if (state == CircuitState.HALF_OPEN) {
                        try {
                            T result = action.get();
                            reset();
                            return result;
                        } catch (Exception e) {
                            tripBreaker();
                            throw e;
                        }
                    }
                }
                // Fell through: state changed while waiting for lock
                return execute(action);
            }

            try {
                T result = action.get();
                failureCount.set(0);
                return result;
            } catch (Exception e) {
                recordFailure();
                throw e;
            }
        }

        private void recordFailure() {
            int count = failureCount.incrementAndGet();
            if (count >= failureThreshold) {
                tripBreaker();
            }
        }

        private void tripBreaker() {
            state = CircuitState.OPEN;
            lastFailureTime = System.currentTimeMillis();
        }

        private void reset() {
            failureCount.set(0);
            state = CircuitState.CLOSED;
        }
    }
}
